from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the Main and Lookup sheets
wb = load_workbook('input.xlsx')
main_sheet = wb['Main']
lookup_sheet = wb['Lookup']

# Step 1: Delete rows where Company is 'Motorcycle'
rows_to_delete = []
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] == 'Motorcycle':
        rows_to_delete.append(row[0])  # Store the row number

# Delete rows in reverse order to avoid shifting issues
for row_num in sorted(rows_to_delete, reverse=True):
    main_sheet.delete_rows(row_num)

# Step 2: Delete rows where Company is 'Ahmed Sons' and Location is Canada
rows_to_delete = []
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] == 'Ahmed Sons' and row[1] == 'Canada':
        rows_to_delete.append(row[0])  # Store the row number

# Delete rows in reverse order to avoid shifting issues
for row_num in sorted(rows_to_delete, reverse=True):
    main_sheet.delete_rows(row_num)

# Step 3: Change 'Bill Rate of Resource' to 180 for rows where Company is 'National TV' and Location is India
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] == 'National TV' and row[1] == 'India':
        # Find the row number
        row_num = main_sheet.max_row
        for i in range(2, row_num + 1):
            if main_sheet.cell(row=i, column=1).value == row[0] and main_sheet.cell(row=i, column=2).value == row[1]:
                main_sheet.cell(row=i, column=7).value = 180
                break

# Step 4: Insert two new rows immediately following each row where the Company is 'Ahmed Sons'
rows_to_insert = []
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] == 'Ahmed Sons':
        rows_to_insert.append(row[0])  # Store the row number

# Insert rows in reverse order to avoid shifting issues
for row_num in sorted(rows_to_insert, reverse=True):
    main_sheet.insert_rows(row_num + 1, 2)

# Step 5: Perform VLOOKUP to populate Column M with 'working Weeks' data from Lookup sheet
# Match on 'Employee Ids' in Column C from Main sheet
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    employee_id = row[2]
    # Find the matching row in Lookup sheet
    for lookup_row in lookup_sheet.iter_rows(min_row=2, values_only=True):
        if lookup_row[0] == employee_id:
            main_sheet.cell(row=row[0], column=13).value = lookup_row[1]
            break

# Save the workbook
wb.save('output.xlsx')
