from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Initialize a dictionary to store the result for each week
week_result = {}

# Iterate through the rows in the sheet
for row in ws.iter_rows(min_row=2, max_row=92, values_only=True):
    date, emp_num, abs_name, atts_name, week = row

    # Check if the row has "Sick Day" or "Overtime" for the employee
    sick_day = abs_name == "Sick Day"
    overtime = atts_name == "Overtime"

    # If both are present, record the week
    if sick_day and overtime:
        if emp_num not in week_result:
            week_result[emp_num] = set()
        week_result[emp_num].add(week)

# Write the results to the range F2:F92
for row in ws.iter_rows(min_row=2, max_row=92):
    emp_num = row[1].value
    if emp_num in week_result:
        # Check if the current week is in the set and is not the first week
        current_week = row[4].value
        if current_week in week_result[emp_num]:
            # Check if the previous week is different
            prev_week = None
            for r in ws.iter_rows(min_row=2, max_row=92):
                if r[4].value == current_week:
                    prev_week = r[4].value
                    break
            if prev_week != current_week:
                row[5].value = "y"
            else:
                row[5].value = ""
        else:
            row[5].value = ""
    else:
        row[5].value = ""

# Save the workbook as output.xlsx
wb.save('output.xlsx')
