from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook
wb = load_workbook('input.xlsx')

# Access the sheets
front_sheet = wb['Front']
data_sheet = wb['Data']

# Create a dictionary to map dates to agent values
date_to_agent_values = {}

# Iterate through the 'Data' sheet to build the dictionary
# We'll look for rows that have an agent name (not "Totals" or empty)
for row in data_sheet.iter_rows(min_row=3, min_col=1, max_col=15):
    date_cell = row[0]
    if date_cell.value is None:
        continue
    date = date_cell.value
    agent_name = None
    for cell in row:
        if cell.column == 1:
            agent_name = cell.value
        elif agent_name is not None and cell.value is not None:
            # Store the value under the agent name for this date
            if date not in date_to_agent_values:
                date_to_agent_values[date] = {}
            date_to_agent_values[date][agent_name] = cell.value

# Now, for each cell in the 'Front' sheet's B2:C12 range, find the corresponding value
for row_idx in range(2, 13):  # Rows 2 to 12 (inclusive)
    date_cell = front_sheet[f'B{row_idx}']
    target_cell = front_sheet[f'C{row_idx}']

    date = date_cell.value
    if date in date_to_agent_values:
        # Get the agent name from the 'Front' sheet
        agent_name = front_sheet[f'A{row_idx}'].value
        if agent_name in date_to_agent_values[date]:
            target_cell.value = date_to_agent_values[date][agent_name]
        else:
            target_cell.value = None  # Return blank if agent not found
    else:
        target_cell.value = None  # Return blank if date not found

# Save the workbook
wb.save('output.xlsx')
